import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int n;
    static long[] bit;

    static void add(int idx, long delta) {
        while (idx <= n) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }

    static long sum(int idx) {
        long res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();

        n = sc.nextInt();
        int q = sc.nextInt();

        bit = new long[n + 2];
        int[] floors = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            floors[i] = sc.nextInt();
            add(i, floors[i]);
        }

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < q; i++) {
            int type = sc.nextInt();

            if (type == 0) {
                int k = sc.nextInt();
                int p = sc.nextInt();

                long delta = (long) p - floors[k];
                floors[k] = p;
                add(k, delta);
            } else {
                int k = sc.nextInt();
                sb.append(sum(k)).append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
